import {parsePcap,summarize} from './parser.js';
import {loadMl} from './ml.js';
const $=id=>document.getElementById(id), colors={TCP:'#345e78',HTTP:'#66baa4',UDP:'#efb86a',ICMP:'#b0a4d2',OTHER:'#a9b6c2','IPv4-FRAGMENT':'#c4a989',MALFORMED:'#cf8b83',ARP:'#93aa75','IPv4-OTHER':'#aaa'};
let rows=[],summary=summarize([]),filter='All',query='',page=0,sort='number',descending=false;const pageSize=25;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>n.toLocaleString('en-IN');
function badge(p){return `<span class="badge ${escape(p)}">${escape(p)}</span>`;}
function route(){const view=location.hash.slice(1)||'analysis';const known=['analysis','guide','ml','source','report'].includes(view)?view:'analysis';document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==known);document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===known);if(a.dataset.view===known)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(known==='ml')loadMl();if(known==='source'&&!$('code-preview').dataset.loaded)showSource(sources[0]);}
window.addEventListener('hashchange',route);
window.addEventListener('hashchange',()=>window.scrollTo(0,0));
function error(message){$('error').textContent=message;$('error').hidden=!message;}
function loadData(buffer,name,synthetic){
  const decoded=parsePcap(buffer);rows=decoded;summary=summarize(rows);filter='All';query='';page=0;sort='number';descending=false;$('search').value='';
  $('file-name').textContent=name;$('file-meta').textContent=`${number(rows.length)} packets · Classic PCAP · ${synthetic?'Constructed classroom fixture':'Analyzed on this device'}`;
  $('dataset-tag').textContent=synthetic?'SYNTHETIC DEMO':'LOCAL CAPTURE';$('dataset-tag').style.display='';error('');renderSummary();renderChips();renderTable();
}
async function demo(){try{const res=await fetch('samples/synthetic_localhost.pcap');if(!res.ok)throw Error('Could not load the sample. Please reload the page.');loadData(await res.arrayBuffer(),'synthetic_localhost.pcap',true);}catch(e){error(e.message);}}
async function upload(file){if(!file)return;location.hash='analysis';if(file.size>20*1024*1024){error('Choose a capture smaller than 20 MB. You can export a smaller packet selection in Wireshark.');return;}try{loadData(await file.arrayBuffer(),file.name,false);}catch(e){error(e.message+' Your previous analysis has been kept.');}$('file-input').value='';}
$('upload-top').onclick=()=>$('file-input').click();document.querySelectorAll('.open-capture').forEach(b=>b.onclick=()=>$('file-input').click());$('file-input').onchange=e=>upload(e.target.files[0]);$('reset-demo').onclick=demo;
const zone=$('drop-zone');['dragenter','dragover'].forEach(name=>zone.addEventListener(name,e=>{e.preventDefault();zone.classList.add('drag');}));['dragleave','drop'].forEach(name=>zone.addEventListener(name,e=>{e.preventDefault();zone.classList.remove('drag');}));zone.addEventListener('drop',e=>upload(e.dataTransfer.files[0]));
function renderSummary(){
  $('stat-packets').textContent=number(summary.packets);$('stat-bytes').textContent=number(summary.bytes);$('stat-duration').textContent=summary.duration.toFixed(3)+' s';$('stat-rate').textContent=summary.rate>=1000?(summary.rate/1000).toFixed(2)+' kb/s':summary.rate.toFixed(0)+' b/s';$('donut-total').textContent=number(summary.packets);
  let start=0;const stops=[];
  $('legend').innerHTML=Object.entries(summary.protocols).map(([p,count])=>{const pc=summary.packets?count/summary.packets*100:0;stops.push(`${colors[p]||'#a9b6c2'} ${start}% ${start+pc}%`);start+=pc;return `<div class="legend-row"><span class="legend-label"><i class="dot" style="background:${colors[p]||'#a9b6c2'}"></i>${escape(p)}</span><span>${count} <small> / ${pc.toFixed(1)}%</small></span></div>`;}).join('')||'<p class="muted">No packets in this file</p>';
  $('donut').style.background=stops.length?`conic-gradient(${stops.join(',')})`:'#edf0f3';
  $('conversations').innerHTML=Object.entries(summary.flows).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([name,count])=>{const [proto,endpoints]=name.split(' | ');return `<div class="flow"><div class="flow-head">${badge(proto)}<span class="flow-count">${count} packets</span></div><div class="flow-endpoints">${escape(endpoints)}</div></div>`;}).join('')||'<p class="muted">No decoded IPv4 conversations.</p>';
  const statuses=Object.entries(summary.statuses).map(([key,n])=>`${n} ${key}`).join(' · ');$('transport-note').textContent=`Transport: ${Object.entries(summary.transports).map(([key,n])=>key+' '+n).join(' · ')||'none'}. ${statuses}`;
}
function renderChips(){const types=['All',...Object.keys(summary.protocols)];$('chips').innerHTML=types.map(p=>`<button class="chip ${p===filter?'active':''}" data-protocol="${escape(p)}" aria-pressed="${p===filter}">${escape(p)}${p==='All'?' packets':''}</button>`).join('');$('chips').querySelectorAll('button').forEach(b=>b.onclick=()=>{filter=b.dataset.protocol;page=0;renderChips();renderTable();});}
function filtered(){return rows.filter(r=>(filter==='All'||r.protocol===filter)&&[r.number,r.source,r.destination,r.sourcePort,r.destinationPort,r.protocol,r.info,r.status].join(' ').toLowerCase().includes(query)).sort((a,b)=>(a[sort]-b[sort])*(descending?-1:1));}
function renderTable(){const data=filtered(),pages=Math.max(1,Math.ceil(data.length/pageSize));page=Math.min(page,pages-1);const slice=data.slice(page*pageSize,(page+1)*pageSize);$('packet-rows').innerHTML=slice.map(r=>`<tr tabindex="0" data-number="${r.number}" aria-label="Inspect packet ${r.number}, ${escape(r.protocol)}"><td>${r.number}</td><td>${(r.timestamp-summary.earliest).toFixed(6)}</td><td>${escape(r.source||'—')}${r.sourcePort!==''?':'+r.sourcePort:''}</td><td>${escape(r.destination||'—')}${r.destinationPort!==''?':'+r.destinationPort:''}</td><td>${badge(r.protocol)}</td><td>${r.length}</td><td title="${escape(r.info)}">${escape(r.info)}</td></tr>`).join('');
  $('table-count').textContent=data.length?`Showing ${page*pageSize+1}–${Math.min((page+1)*pageSize,data.length)} of ${number(data.length)} packets`:'0 matching packets';$('empty').hidden=data.length>0;$('prev-page').disabled=page===0;$('next-page').disabled=page>=pages-1;
  $('packet-rows').querySelectorAll('tr').forEach(tr=>{const open=()=>details(rows.find(r=>r.number===Number(tr.dataset.number)));tr.onclick=open;tr.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}};});
}
$('search').oninput=e=>{query=e.target.value.trim().toLowerCase();page=0;renderTable();};$('prev-page').onclick=()=>{page--;renderTable();};$('next-page').onclick=()=>{page++;renderTable();};
for(const [id,field] of [['sort-time','timestamp'],['sort-length','length']])$(id).onclick=()=>{descending=sort===field?!descending:false;sort=field;page=0;renderTable();};
function details(r){$('detail-title').textContent=`Packet ${r.number} · ${r.protocol}`;const fields={'Relative time':(r.timestamp-summary.earliest).toFixed(6)+' s','Source':r.source||'Not decoded','Destination':r.destination||'Not decoded','Source port':r.sourcePort!==''?r.sourcePort:'Not applicable','Destination port':r.destinationPort!==''?r.destinationPort:'Not applicable','Transport':r.transport,'Frame length':r.length+' bytes','Captured length':r.captured+' bytes','Status':r.status,'Information':r.info};if(r.sequence!==null){fields['TCP flags']=r.flags;fields['Sequence']=r.sequence;fields['Acknowledgement']=r.acknowledgement;}$('packet-detail').innerHTML=Object.entries(fields).map(([k,v])=>`<div class="detail-row"><span>${escape(k)}</span><b>${escape(v)}</b></div>`).join('');$('packet-dialog').showModal();}
$('close-detail').onclick=()=>$('packet-dialog').close();$('packet-dialog').addEventListener('click',e=>{if(e.target===$('packet-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('export').onclick=()=>{const data=filtered();const fields=['number','timestamp','source','destination','sourcePort','destinationPort','transport','protocol','length','captured','info','status'];const csv=fields.join(',')+'\r\n'+data.map(r=>fields.map(k=>'"'+String(r[k]).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='packets.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const sources=[{name:'train_compare.py',url:'ml/train_compare.py',description:'Train, tune and evaluate boosting, classification and clustering models on the three supplied datasets.'},{name:'ML_README.md',url:'ml/README.md',description:'Experimental method, results, reproducibility and limitations.'},{name:'parser.js',url:'parser.js',description:'Browser PCAP reader, IPv4 and transport decoder, and summary statistics.'},{name:'app.js',url:'app.js',description:'File handling, packet explorer, chart rendering, filters and exports.'},{name:'index.html',url:'index.html',description:'Accessible application structure and project documentation.'},{name:'style.css',url:'style.css',description:'Responsive visual design for desktop and mobile.'},{name:'analyzer.py',url:'source/analyzer.py',description:'Standalone Python analyzer with HTML, CSV and JSON exports.'},{name:'generate_traffic.py',url:'source/generate_traffic.py',description:'Real HTTP and UDP localhost traffic generator. Run this on your laptop while Wireshark records.'},{name:'make_sample.py',url:'source/make_sample.py',description:'Constructs the reproducible 16-packet sample with valid checksums.'},{name:'README.md',url:'source/README.md',description:'Python installation, commands, Wireshark guidance and limitations.'},{name:'test_project.py',url:'source/test_project.py',description:'Nine Python unit and integration tests.'},{name:'parser.test.mjs',url:'source/parser.test.mjs',description:'Browser decoder tests executed with Node.js.'}];
$('source-files').innerHTML=sources.map((s,i)=>`<button data-index="${i}">${s.name}</button>`).join('');$('source-files').querySelectorAll('button').forEach(b=>b.onclick=()=>showSource(sources[Number(b.dataset.index)]));
let sourceRequest=0;
async function showSource(s){const request=++sourceRequest;$('code-title').textContent=s.name;$('code-description').textContent=s.description;$('code-download').href=s.url;$('code-preview').textContent='Loading source…';document.querySelectorAll('#source-files button').forEach(b=>b.classList.toggle('active',sources[Number(b.dataset.index)]===s));try{const res=await fetch(s.url);if(!res.ok)throw Error('Source could not be loaded.');const code=await res.text();if(request!==sourceRequest)return;$('code-preview').textContent=code;$('code-preview').dataset.loaded='true';}catch(e){if(request===sourceRequest)$('code-preview').textContent=e.message;}}
route();demo();
